{"status":"candidate","chosen_option":"offline_dynamic_connectivity","assumptions":["Vertices are numbered 1 through n, and the given operation format and constraints are valid.","The implementation stores an edge as an unordered endpoint pair; self-loops are harmless to the rollback DSU."],"observations":[{"statement":"The task requires a standard-library Python 3.11 program that answers component-size queries under edge additions and removals with multiplicity.","source_ids":["task"]},{"statement":"Supplied examples include duplicate/reversed edges, unmatched removals, self-loops, and isolated vertices.","source_ids":["public1","public2","public3","public4"]}],"artifact":{"code":"import sys
from collections import defaultdict


def main():
    data = sys.stdin.buffer
    first = data.readline().split()
    if not first:
        return
    n, q = map(int, first)
    ops = []
    # For each unordered edge, keep its multiplicity and the start of its
    # current positive-multiplicity time interval (if active).
    multiplicity = defaultdict(int)
    start = {}
    intervals = []  # (left inclusive, right exclusive, u, v)

    for t in range(q):
        parts = data.readline().split()
        typ = parts[0]
        u = int(parts[1]) - 1
        if typ == b'?':
            ops.append((typ, u, -1))
        else:
            v = int(parts[2]) - 1
            if u > v:
                u, v = v, u
            key = (u, v)
            ops.append((typ, u, v))
            if typ == b'+':
                if multiplicity[key] == 0:
                    start[key] = t
                multiplicity[key] += 1
            elif multiplicity[key] > 0:
                multiplicity[key] -= 1
                if multiplicity[key] == 0:
                    intervals.append((start.pop(key), t, u, v))

    for (u, v), left in start.items():
        intervals.append((left, q, u, v))

    size = 1
    while size < q:
        size <<= 1
    tree = [[] for _ in range(2 * size)]
    for left, right, u, v in intervals:
        if left >= right:
            continue
        l, r = left + size, right + size
        while l < r:
            if l & 1:
                tree[l].append((u, v))
                l += 1
            if r & 1:
                r -= 1
                tree[r].append((u, v))
            l >>= 1
            r >>= 1

    parent = list(range(n))
    comp_size = [1] * n
    history = []

    def find(x):
        while parent[x] != x:
            x = parent[x]
        return x

    def unite(a, b):
        a = find(a)
        b = find(b)
        if a == b:
            history.append(None)
            return
        if comp_size[a] < comp_size[b]:
            a, b = b, a
        history.append((b, a, comp_size[a]))
        parent[b] = a
        comp_size[a] += comp_size[b]

    answers = []

    def traverse(node, left, right):
        checkpoint = len(history)
        for u, v in tree[node]:
            unite(u, v)
        if right - left == 1:
            if left < q and ops[left][0] == b'?':
                answers.append(str(comp_size[find(ops[left][1])]))
        else:
            mid = (left + right) >> 1
            traverse(node << 1, left, mid)
            traverse(node << 1 | 1, mid, right)
        while len(history) > checkpoint:
            change = history.pop()
            if change is not None:
                child, root, old_size = change
                parent[child] = child
                comp_size[root] = old_size

    if q:
        traverse(1, 0, size)
    sys.stdout.write('\n'.join(answers))
    if answers:
        sys.stdout.write('\n')


if __name__ == '__main__':
    main()
